"""Test harness: import gateway.py and run synthetic batches."""
import importlib.util, json, sys

spec = importlib.util.spec_from_file_location("gw", "/workspace/submission/gateway.py")
gw = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gw)

BASE = {
    "directory": {
        "sip:ember@studio.test": ["sip:e1@alias.studio.test", "tel:+12025550121"],
        "sip:desk@sales.test": ["tel:+12025550122"],
        "sip:far@foreign.test": ["tel:+13035550001"],
    },
    "accounts": {
        "session-k": {"primary": "sip:ember@studio.test", "allow": ["sip:desk@sales.test"]},
        "solo": {"primary": "sip:desk@sales.test", "allow": []},
        "foreign": {"primary": "sip:far@foreign.test", "allow": []},
    },
    "gateways": {
        "edge": {"local_domains": ["studio.test", "sales.test"], "peers": {}},
        "inside": {"local_domains": [], "peers": {"edge": ["studio.test", "sales.test"]}},
        "narrow": {"local_domains": ["studio.test"], "peers": {"edge": ["sales.test"]}},
        "mixed": {"local_domains": ["studio.test"], "peers": {"edge": ["studio.test"], "other": ["foreign.test"]}},
    },
}

def req(method="MESSAGE", ruri="sip:inbox@relay.test", frm="<sip:ember@studio.test>",
       tag="q7", to="<sip:inbox@relay.test>", to_tag=None, callid="sample-73",
       cseq="9 MESSAGE", extra=(), ctype="text/plain", body="hello", privacy=None,
       cl=None, fold=None):
    lines = ["%s %s SIP/2.0" % (method, ruri)]
    if isinstance(frm, str):
        frm = [frm]
    for f in frm:
        lines.append("From: " + f + (";tag=" + tag if tag and ";tag=" not in f and not f.endswith(";") else ""))
    lines.append("To: " + to + (";tag=" + to_tag if to_tag else ""))
    lines.append("Call-ID: " + callid)
    lines.append("CSeq: " + cseq)
    if privacy is not None:
        lines.append("Privacy: " + privacy)
    for e in extra:
        lines.append(e)
    if ctype is not None:
        lines.append("Content-Type: " + ctype)
    b = body
    lines.append("Content-Length: " + (str(len(b)) if cl is None else cl))
    return "\r\n".join(lines) + "\r\n\r\n" + b

def run(jobs, base=None):
    batch = json.loads(json.dumps(base or BASE))
    batch["jobs"] = jobs
    return gw.process(batch)["results"]

def one(raw, gateway="edge", ingress=None, trusted_out=True, base=None):
    if ingress is None:
        ingress = {"kind": "local", "subject": "session-k"}
    job = {"gateway": gateway, "ingress": ingress, "trusted_out": trusted_out}
    if isinstance(raw, int):
        job["source"] = raw
    else:
        job["raw"] = raw
    return run([job], base)[0]

def show(r):
    if r["status"] == "accept":
        return "accept %s %s private=%s\n   %r" % (r["identity"], r["basis"], r["private"], r["wire"])
    return "reject " + r["reason"]
PYEOF
